    @BeforeEach void resetNotifications(){db.update("UPDATE ops.business_notification SET state='CANCELLED'");db.update("UPDATE ops.notification_delivery SET state='CANCELLED',lease_token=NULL,lease_until=NULL");}
    /** 通过真实目录与人工质量接口建立尚未批准的双节点归档复核。 */
    private UUID pendingFlow(){UUID box=(UUID)catalog.box(context(archivistB,"ARCHIVE_COLLECTION",ApiController.COLLECTION,"CREATE_BOX",null),Sql.map("departmentId",b.toString(),"title","通知合成盒","safeTitle","通知演示盒","classification","GENERAL","retentionCode","10","archiveDate",LocalDate.now(WorkCalendarService.ZONE).toString(),"physicalFileCount",0,"location","合成运维库位","keywords",List.of("合成通知"),"templateVersionId",templateBox.toString(),"categoryCode","ADMIN","ownerId",people.get("managerB").toString(),"numberMonth",LocalDate.now(WorkCalendarService.ZONE).withDayOfMonth(1).toString(),"carrierType","PAPER","extensionValues",Sql.map("paperTags",List.of("纸质原件")))).get("id");return review(archivistB,"BOX",box,null);}
    private Map<String,Object> task(UUID flow){return db.required("SELECT s.* FROM workflow.step s JOIN workflow.instance w ON w.current_step_id=s.id WHERE w.id=?",flow);}
    private UUID notice(UUID step){return (UUID)db.required("SELECT id FROM ops.business_notification WHERE source_kind='WORKFLOW_STEP' AND source_id=? AND state<>'CANCELLED' ORDER BY created_at DESC LIMIT 1",step).get("id");}
    private Path mailbox(){return Path.of(System.getenv("IMS_PLATFORM_NOTIFICATIONS_LOCAL_DIRECTORY"));}
    private void deliveryFailure(boolean fail)throws Exception{Files.createDirectories(mailbox());Path marker=mailbox().resolve("instance");Files.writeString(marker,fail?UUID.randomUUID().toString():db.required("SELECT id FROM platform_meta.instance").get("id").toString());PrivateFiles.restrict(mailbox());}
    private int queueVersion(UUID id){return ((Number)db.required("SELECT row_version FROM ops.notification_delivery WHERE id=?",id).get("row_version")).intValue();}
    /** 大量取消历史不能使领取扫描全表；用服务器三秒上限验证真实查询，不放宽生产超时。 */
    @Test @Order(0) void claimDoesNotAuthorizeEveryHistoricalNotification(){
        db.update("INSERT INTO ops.business_notification(id,event_key,user_id,source_kind,source_id,kind,state) SELECT gen_random_uuid(),'PERF:'||gen_random_uuid(),?,'WORKFLOW_STEP',gen_random_uuid(),'TASK_AVAILABLE','CANCELLED' FROM generate_series(1,1500)",people.get("managerB"));
        pendingFlow();
        var work=new org.springframework.transaction.support.TransactionTemplate(transactionManager).execute(status->{db.update("SET LOCAL statement_timeout='3s'");assertEquals(1L,notifications.list(actors.get(people.get("managerB")),Map.of()).get("total"));return notifications.claim();});
        assertNotNull(work);assertEquals(people.get("managerB"),work.get("user_id"));
    }
    /** 业务事务回滚时通知与投递也回滚，不发生提前发送。 */
