    /** 决定后旧待办即时失效，消息失败不阻止后续真实审批和结果提交。 */
    @Test @Order(3) void decisionStopsOldTaskAndPublishesNextAndResult()throws Exception{UUID flow=pendingFlow();var first=task(flow);UUID id=notice((UUID)first.get("id"));workflow.decide(context(actors.get(first.get("assignee_id")),"WORKFLOW_STEP",(UUID)first.get("id"),"DECIDE_STEP",1),(UUID)first.get("id"),Sql.map("result","APPROVE","comment","合成批准首节点"));assertEquals(0,db.count("SELECT CASE WHEN ops.notification_current(?,?) THEN 1 ELSE 0 END",id,first.get("assignee_id")));deliveryFailure(true);try{notifications.tick();approve(flow);assertEquals("APPROVED",db.required("SELECT state FROM workflow.instance WHERE id=?",flow).get("state"));assertEquals(1,db.count("SELECT count(*) FROM ops.business_notification WHERE source_id=? AND kind='WORKFLOW_APPROVED'",flow));}finally{deliveryFailure(false);}}
    /** 并发工作器只有一个能领取同一任务。 */
    @Test @Order(4) void concurrentWorkersOnlyOneClaims(){pendingFlow();var start=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(()->{start.await();return notifications.claim();});var two=pool.submit(()->{start.await();return notifications.claim();});start.countDown();assertNotEquals(one.get()!=null,two.get()!=null);}catch(Exception failure){throw new RuntimeException(failure);}}
    /** 投递刷盘后进程中断，租约恢复沿原投递号去重；旧工作器不能确认新租约。 */
    @Test @Order(5) void expiredLeaseAfterDurableSendDoesNotDuplicate()throws Exception{pendingFlow();deliveryFailure(false);var first=notifications.claim();UUID id=(UUID)first.get("id");String receipt=messageTransport.send(new com.company.platform.operations.BusinessMessageTransport.Message(id,(UUID)first.get("notification_id"),(UUID)first.get("user_id"),first.get("company_email").toString(),first.get("kind").toString(),first.get("source_kind").toString(),(UUID)first.get("source_id")));byte[] content=Files.readAllBytes(mailbox().resolve(id+".json"));db.update("UPDATE ops.notification_delivery SET lease_until=CURRENT_TIMESTAMP-interval '1 second' WHERE id=?",id);var next=notifications.claim();assertEquals(id,next.get("id"));assertNotEquals(first.get("lease_token"),next.get("lease_token"));notifications.deliver(first);assertEquals("RUNNING",db.required("SELECT state FROM ops.notification_delivery WHERE id=?",id).get("state"));notifications.deliver(next);assertEquals(receipt,db.required("SELECT receipt_id FROM ops.notification_delivery WHERE id=?",id).get("receipt_id"));assertArrayEquals(content,Files.readAllBytes(mailbox().resolve(id+".json")));assertEquals(1,db.count("SELECT count(*) FROM ops.notification_attempt WHERE delivery_id=? AND outcome='UNKNOWN'",id));assertEquals(1,db.count("SELECT count(*) FROM ops.notification_attempt WHERE delivery_id=? AND outcome='SENT'",id));}
    /** 初次加三次重试后转人工；重复人工操作只重新排队一次，业务从未被再次执行。 */
    @Test @Order(6) void retryScheduleManualQueueAndIdempotentRecovery()throws Exception{UUID flow=pendingFlow();deliveryFailure(true);UUID id=null;try{int[] delays={60,300,900};for(int attempt=0;attempt<4;attempt++){var work=notifications.claim();assertNotNull(work);id=(UUID)work.get("id");notifications.deliver(work);var row=db.required("SELECT *,extract(epoch FROM next_run_at-CURRENT_TIMESTAMP)::integer AS delay FROM ops.notification_delivery WHERE id=?",id);assertEquals(attempt==3?"MANUAL":"RETRY",row.get("state"));if(attempt<3)assertTrue(Math.abs(((Number)row.get("delay")).intValue()-delays[attempt])<3);db.update("UPDATE ops.notification_delivery SET next_run_at=CURRENT_TIMESTAMP-interval '1 second' WHERE id=?",id);}assertEquals(0,notifications.tick());var ctx=context(supervisor,"NOTIFICATION_DELIVERY",id,"RETRY_NOTIFICATION",queueVersion(id));var body=Sql.map("reason","已修复合成本机投递箱，人工重试");notifications.retry(ctx,id,body);notifications.retry(ctx,id,body);assertEquals(4,db.count("SELECT attempt_count FROM ops.notification_delivery WHERE id=?",id));assertEquals("PENDING",db.required("SELECT state FROM workflow.instance WHERE id=?",flow).get("state"));}finally{deliveryFailure(false);}notifications.tick();assertEquals("SENT",db.required("SELECT state FROM ops.notification_delivery WHERE id=?",id).get("state"));assertEquals(5,db.count("SELECT attempt_count FROM ops.notification_delivery WHERE id=?",id));}
